WITH scored AS (SELECT id, promo_code, starts_on, ends_on, STDDEV_SAMP(discount_pct) OVER (PARTITION BY channel) AS channel_stddev_samp_discount_pct, SUM(discount_pct) OVER w_ordered AS running_discount_pct, ROW_NUMBER() OVER (ORDER BY discount_pct, id) AS event_seq FROM promotions WINDOW w_ordered AS (ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, promo_code, ends_on, running_discount_pct, CASE WHEN promo_code RLIKE '^(BUNDLE|SPRING10)$' THEN 'GROUP_B' WHEN promo_code RLIKE '^(VIP|WELCOME5)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS promo_code_zone FROM scored
